const $=s=>document.querySelector(s),key='focuslane-experiment-local-v1';let db;try{db=JSON.parse(localStorage.getItem(key))||{events:[],sessions:[]}}catch{db={events:[],sessions:[]}}let chosen=new globalThis['URL'](location.href).searchParams.get('variant');let source='Explicit query assignment';if(!/^[A-E]$/.test(chosen||'')){chosen=localStorage.getItem('focuslane-assignment');if(!/^[A-E]$/.test(chosen||'')){chosen='ABCDE'[Math.floor(Math.random()*5)];localStorage.setItem('focuslane-assignment',chosen)}source='Browser-local random assignment'}let variant=chosen,custom=false,current,started,activeFrom,activeMs=0,maxscroll=0,engaged=false,formstart=false,complete=false,heat=false,tour=0;
const copy={A:'Control A · Proposed baseline; no historical benchmark supplied.',B:'Headline B · Benefit-focused headline only; everything else matches A.',C:'CTA C · First-person button copy only; everything else matches A.',D:'Layout D · Image-left order only; everything else matches A.',E:'Combined E · Unproven headline + CTA + layout candidate, not confirmed winners.'};
function save(){try{localStorage.setItem(key,JSON.stringify(db))}catch{}}
function event(type,detail={}){if(custom)return;db.events.push({time:new Date().toISOString(),variant,type,...detail});if(db.events.length>3000)db.events.shift();save()}
function flush(){if(!current)return;if(activeFrom){activeMs+=performance.now()-activeFrom;activeFrom=performance.now()}Object.assign(current,{activeSeconds:Math.round(activeMs/1000),scrollDepth:maxscroll,engaged,formStarted:formstart,completed:complete,finalized:true});save()}
function start(){if(custom){current=null;return}activeMs=0;maxscroll=0;engaged=false;formstart=false;complete=false;activeFrom=document.hidden?null:performance.now();current={variant,startedAt:new Date().toISOString(),finalized:false,clicks:[]};db.sessions.push(current);if(db.sessions.length>1000)db.sessions.shift();event('view')}
const dims={
headline:['Get a clearer workday in 10 minutes','Stop losing your best ideas','Want more room for focused work?','Join people who choose a calmer workday — illustrative copy','Last chance to simplify your week — example only'],
subheadline:['Tasks, notes and projects in one workspace.','Spend less time organizing and more time doing.','Try the local demo without a card or commitment.','A calmer routine, told through an illustrative customer story.','Plan three priorities and one next step each morning.'],
cta:['Get Started','Start Free Trial','Download Now','Get My Copy','Sign Up','Create Account','Start My Free Trial','Claim Your Spot'],
design:['Purple color','Large button','Square corners','With arrow icon','No shadow'],
layout:['Image left','Video-style tour','Long form','Short form','Single column'],
proof:['Below headline','Near CTA','In hero illustration','Dedicated section','Floating element'],
form:['Email only','Email + name','Email + company','Multi-step','Popup'],
trust:['No badges','Illustrative trust badge','Illustrative quote','Text logo strip','Guarantee near form','Security explanation'],
urgency:['None','Illustrative timer','Scarcity example','Limited-time example','Stock example','Deadline example'],
image:['Product shot','People concept','Before / after','Abstract illustration','Screenshot-style interface'],
pricing:['Price hidden','Monthly','Annual','Illustrative discount','Comparison','Value framing']};
const labels={headline:'Headline angle',subheadline:'Supporting copy',cta:'CTA wording',design:'CTA design',layout:'Layout',proof:'Social proof placement',form:'Form structure',trust:'Trust elements',urgency:'Urgency messaging',image:'Visual approach',pricing:'Pricing display'};
Object.entries(labels).forEach(([v,t])=>$('#dimension').add(new Option(t,v)));
function baseline(){document.querySelectorAll('[data-v]').forEach(b=>b.classList.toggle('active',b.dataset.v===variant));$('#hypothesis').textContent=copy[variant];$('#assignment').textContent=source;$('#headline').textContent=['B','E'].includes(variant)?'Get a clearer workday in 10 minutes.':'Less busywork.\nMore headspace.';$('#subhead').textContent='Bring your tasks, notes and next big idea into one thoughtful workspace. Make space for the work you love.';$('#cta').textContent=['C','E'].includes(variant)?'Start My Free Trial':'Get Started';$('#cta').removeAttribute('style');$('#hero').className='hero'+(['D','E'].includes(variant)?' reverse':'');$('#proof').textContent='ILLUSTRATIVE PRODUCT · NO CUSTOMER CLAIMS';$('#proof').removeAttribute('style');$('#proof').hidden=false;$('#price').hidden=false;$('#price').innerHTML='$12 / month<br><small>Illustrative pricing</small>';$('#guarantee').textContent='No card. No pressure. Just a local product demo.';$('#urgency').hidden=true;$('#benefits').hidden=false;$('#art').removeAttribute('style');$('#imagecaption').textContent='Original interface illustration · sample tasks';$('#play').hidden=true;$('#extralabel').hidden=true;$('#extra').required=false;$('#extralabel').firstChild.textContent='Your name';$('#email').hidden=false;$('#email').required=true;$('#submit').textContent='Preview my workspace →';$('#formstatus').textContent='';$('#form').reset();$('#customnote').textContent='';document.title='Focuslane — Variant '+variant+' / Experiment Studio';$('#dots').replaceChildren()}
function switchv(v){flush();variant=v;custom=false;const u=new globalThis['URL'](location.href);u.searchParams.set('variant',v);history.replaceState(null,'',u);source='Explicit query assignment';$('#dimension').value='';$('#alternative').innerHTML='<option>Choose a dimension first</option>';$('#alternative').disabled=true;baseline();start();metrics()}
const oldBaseline=baseline;baseline=function(){oldBaseline();$('#subhead').after($('#proof'));$('.actions').after($('#guarantee'));$('#guarantee').hidden=false;$('.floatcard').textContent='✓ One less thing on your mind.';$('#art').removeAttribute('data-image');$('#alternateimage')?.remove()};
document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>switchv(b.dataset.v));
$('#dimension').onchange=()=>{const d=$('#dimension').value;$('#alternative').replaceChildren();$('#alternative').disabled=!d;if(!d){switchv('A');return}dims[d].forEach(t=>$('#alternative').add(new Option(t,t)));apply()};
$('#alternative').onchange=apply;
function apply(){const d=$('#dimension').value,v=$('#alternative').value;flush();variant='A';custom=true;baseline();current=null;$('#hypothesis').textContent='CUSTOM / Control A + one '+labels[d].toLowerCase()+' change';$('#assignment').textContent='Excluded from experiment metrics';$('#customnote').textContent='Sandbox only: '+labels[d]+' → '+v;
if(d==='headline')$('#headline').textContent=v;
if(d==='subheadline')$('#subhead').textContent=v;
if(d==='cta')$('#cta').textContent=v;
if(d==='design'){if(v==='Purple color')$('#cta').style.background='#8568b7';if(v==='Large button')$('#cta').style.padding='23px 32px';if(v==='Square corners')$('#cta').style.borderRadius='0';if(v==='With arrow icon')$('#cta').textContent+=' →';if(v==='No shadow')$('#cta').style.boxShadow='none'}
if(d==='layout'){if(v==='Image left')$('#hero').classList.add('reverse');if(v==='Video-style tour')$('#play').hidden=false;if(v==='Long form')$('#subhead').textContent+=' Keep context close with a daily priority list, project notes and a simple view of your week. This expanded copy is a test hypothesis, not a promised productivity result.';if(v==='Short form')$('#benefits').hidden=true;if(v==='Single column')$('#hero').classList.add('single')}
if(d==='proof'){const p=$('#proof');p.textContent='“A little clarity goes a long way.” · ILLUSTRATIVE QUOTE';if(v==='Near CTA')$('.actions').after(p);else if(v==='In hero illustration')$('#art').append(p);else if(v==='Dedicated section')$('#benefits').after(p);else if(v==='Floating element'){p.style.cssText='position:fixed;bottom:15px;right:15px;z-index:5;max-width:260px;background:#fff;padding:15px;border:1px solid #ddd;border-radius:8px'}else $('#subhead').after(p)}
else $('#subhead').after($('#proof'));
if(d==='form'){if(['Email + name','Email + company'].includes(v)){$('#extralabel').hidden=false;$('#extra').required=true;$('#extralabel').firstChild.textContent=v==='Email + name'?'Your name':'Company'}if(v==='Multi-step')$('#submit').textContent='Continue to next step →';if(v==='Popup')$('#customnote').textContent+=' · CTA opens a clearly labeled local form dialog.'}
if(d==='trust'){if(v==='No badges')$('#guarantee').hidden=true;else{$('#guarantee').hidden=false;$('#guarantee').textContent={'Illustrative trust badge':'◇ ILLUSTRATIVE BADGE · not a certification','Illustrative quote':'“A calmer start.” · fictional testimonial example','Text logo strip':'NORTH / FIELD / STUDIO · fictional logo examples','Guarantee near form':'Sample guarantee placement · no real purchase or refund offer','Security explanation':'Local demonstration. No form values are transmitted or stored.'}[v]||'';if(v==='Guarantee near form')$('#form').append($('#guarantee'))}}
else{$('#guarantee').hidden=false;$('.actions').after($('#guarantee'))}
if(d==='urgency'&&v!=='None'){$('#urgency').hidden=false;$('#urgency').textContent={'Illustrative timer':'EXAMPLE ONLY · 01:59:00 (static, not a real deadline)','Scarcity example':'EXAMPLE ONLY · 12 sample places remaining','Limited-time example':'EXAMPLE ONLY · A limited-time sample offer','Stock example':'EXAMPLE ONLY · 8 sample seats available','Deadline example':'EXAMPLE ONLY · Registration closes Friday'}[v]}
if(d==='image'){const captions={'Product shot':'Product mockup / Original interface art','People concept':'People concept / Original collaboration illustration','Before / after':'Before: scattered tasks → After: one workspace / illustrative','Abstract illustration':'Abstract focus study / Original gradient artwork','Screenshot-style interface':'Screenshot-style UI / Fictional product, not a real capture'};$('#imagecaption').textContent=captions[v];$('#art').dataset.image=v;const div=document.createElement('div');div.id='alternateimage';if(v==='People concept')div.innerHTML='<div class="people"><i></i><i></i><i></i></div><b>A shared plan.<br>A calmer team.</b>';if(v==='Before / after')div.innerHTML='<div class="beforeafter"><section>BEFORE<p>↗ Scattered notes</p><p>↙ Missed context</p><p>↔ Too many tabs</p></section><section>AFTER<p>✓ One workspace</p><p>✓ Clear priorities</p><p>✓ A next step</p></section></div>';if(v==='Abstract illustration')div.innerHTML='<div class="rings"></div><b>Space to focus.</b>';if(!['Product shot','Screenshot-style interface'].includes(v))$('#art').append(div)}
if(d==='pricing'){if(v==='Price hidden')$('#price').hidden=true;else $('#price').innerHTML={'Monthly':'$12 / month','Annual':'$120 / year<br><small>$10 / month, billed yearly</small>','Illustrative discount':'<s>$144</s> $120 / year<br><small>Illustrative annual discount</small>','Comparison':'Monthly $12 · Annual $120<br><small>Illustrative comparison</small>','Value framing':'$0.40 / day equivalent<br><small>Based on $12 / 30 days; illustrative</small>'}[v]+'<br><small>Illustrative pricing</small>'}
metrics()}
$('#reset').onclick=()=>switchv('A');
$('#cta').onclick=()=>{engaged=true;event('cta_click');if(custom&&$('#dimension').value==='form'&&$('#alternative').value==='Popup'){const form=$('#form');$('#modalcopy').textContent='Local demo form. No submission leaves this browser.';$('#modalcopy').after(form);$('#nexttour').hidden=true;$('#modal').showModal();$('#modal').addEventListener('close',()=>{$('#trial').append(form);$('#nexttour').hidden=false},{once:true})}else $('#trial').scrollIntoView({behavior:'smooth'})};
$('#form').addEventListener('input',()=>{if(!formstart){formstart=true;event('form_start')}engaged=true});
$('#form').onsubmit=e=>{e.preventDefault();engaged=true;if(custom&&$('#dimension').value==='form'&&$('#alternative').value==='Multi-step'&&$('#extralabel').hidden){$('#extralabel').hidden=false;$('#extra').required=true;$('#submit').textContent='Preview my workspace →';$('#extra').focus();return}if(!complete)event('demo_completion');complete=true;$('#formstatus').textContent='Demo complete. Your preview is ready; no account was created and no data was sent.';$('#form').reset();flush();metrics()};
$('#canvas').addEventListener('click',e=>{engaged=true;if(custom)return;const r=$('#canvas').getBoundingClientRect();const point={x:Math.round((e.clientX-r.left)/r.width*10000)/100,y:Math.round((e.clientY-r.top)/r.height*10000)/100};current?.clicks.push(point);event('canvas_click',point);if(heat)draw()});
window.addEventListener('scroll',()=>{maxscroll=Math.max(maxscroll,Math.min(100,Math.round((scrollY+innerHeight)/document.documentElement.scrollHeight*100)))},{passive:true});document.addEventListener('visibilitychange',()=>{flush();if(document.hidden)activeFrom=null;else activeFrom=performance.now()});addEventListener('pagehide',flush);
function metrics(){const views=db.sessions.length,conv=db.events.filter(e=>e.type==='demo_completion').length;$('#metrics').innerHTML=`<article>LOCAL PREVIEW VIEWS<strong>${views}</strong>Not unique visitors</article><article>LOCAL DEMO COMPLETIONS<strong>${conv}</strong>Not business conversions</article><article>WINNER STATUS<strong>Undetermined</strong>No valid inference from this sandbox</article>`;$('#rows').innerHTML='ABCDE'.split('').map(v=>{const s=db.sessions.filter(s=>s.variant===v),f=s.filter(s=>s.finalized),c=s.filter(s=>s.completed).length,starts=f.filter(s=>s.formStarted),bounce=f.length?Math.round(f.filter(s=>!s.engaged).length/f.length*100)+'%':'—';return `<tr><td>${v}${v==='A'?' / Control':''}</td><td>${s.length}</td><td>${c}</td><td>${s.length?(c/s.length*100).toFixed(1)+'%':'—'}</td><td>${bounce}</td><td>${f.length?Math.round(f.reduce((n,s)=>n+(s.activeSeconds||0),0)/f.length)+'s':'—'}</td><td>${f.length?Math.round(f.reduce((n,s)=>n+(s.scrollDepth||0),0)/f.length)+'%':'—'}</td><td>${starts.length?Math.round(starts.filter(s=>!s.completed).length/starts.length*100)+'%':'—'}</td></tr>`}).join('')}
function draw(){$('#dots').replaceChildren();if(!heat)return;db.sessions.filter(s=>s.variant===variant).flatMap(s=>s.clicks||[]).slice(-200).forEach(p=>{const i=document.createElement('i');i.style.left=p.x+'%';i.style.top=p.y+'%';$('#dots').append(i)})}
$('#heat').onclick=()=>{heat=!heat;$('#heat').textContent=heat?'Hide local click map':'Show local click map';draw()};$('#data').onclick=()=>{flush();metrics();$('#insights').scrollIntoView({behavior:'smooth'})};$('#export').onclick=()=>{flush();const a=document.createElement('a'),u=globalThis['URL'].createObjectURL(new Blob([JSON.stringify({notice:'Local demo only; no form values stored; not production evidence.',...db},null,2)],{type:'application/json'}));a.href=u;a.download='focuslane-local-events.json';a.click();setTimeout(()=>globalThis['URL'].revokeObjectURL(u),1000);metrics()};
$('#play').onclick=()=>{tour=0;$('#modalcopy').textContent='1 / Bring your priorities into a single workspace.';$('#modal').showModal()};$('#nexttour').onclick=()=>{tour=(tour+1)%3;$('#modalcopy').textContent=['1 / Bring your priorities into a single workspace.','2 / Keep tasks and notes close to the project.','3 / Review your week and choose one next step.'][tour]};baseline();start();metrics();
